/**
 * Generates the web CSS (and a JSON snapshot) from the authoritative TypeScript tokens.
 * Runs after `tsc` (see package.json "build"). Outputs, all under dist/theme/:
 *   tokens.css  – CSS custom properties only (framework neutral)
 *   theme.css   – tokens + Tailwind 4 `@theme inline` mapping + base + shared component classes
 *   tokens.json – resolved tokens (light/dark palettes, shadows) for tooling and parity tests
 * The generated files are committed (dist/ is tracked) so deployments need no build step for the shared package.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'dist', 'theme');
const t = await import(new URL('../dist/theme/index.js', import.meta.url));

const resolved = t.resolveTheme(t.DEFAULT_THEME_CONFIG);
const light = { ...t.fontVariables(resolved.typography), ...t.staticVariables(), ...t.schemeVariables(resolved, 'light') };
const darkFull = t.schemeVariables(resolved, 'dark');
const dark = t.diffVariables(light, darkFull);

const header = (what) =>
  `/* GENERATED by packages/shared/scripts/build-css.mjs from src/theme — DO NOT EDIT.\n   ${what}\n   Source of truth: Teacher Portal (apps/teacher) tokens, see docs/global-design-system.md */\n`;

const variablesCss = [
  t.renderBlock(':root, [data-theme=\'light\']', light),
  t.renderBlock(t.DARK_SELECTOR, dark),
].join('\n\n');

const base = `body {
  background-color: var(--bg-desk);
  color: var(--ink-primary);
  font-family: var(--font-primary);
  -webkit-font-smoothing: antialiased;
}`;

const components = readFileSync(join(root, 'src', 'theme', 'css', 'components.css'), 'utf8');

mkdirSync(dist, { recursive: true });
writeFileSync(join(dist, 'tokens.css'), `${header('Design tokens as CSS custom properties.')}\n${variablesCss}\n`);
writeFileSync(
  join(dist, 'theme.css'),
  `${header('Tokens + Tailwind theme mapping + shared component classes.')}\n${variablesCss}\n\n${t.renderTailwindTheme()}\n\n${base}\n\n${components}`,
);
writeFileSync(
  join(dist, 'tokens.json'),
  JSON.stringify(
    {
      palettes: resolved.palettes,
      shadows: Object.fromEntries(
        ['light', 'dark'].map((s) => [s, Object.fromEntries(Object.entries(resolved.shadows[s]).map(([k, v]) => [k, t.shadowToCss(v)]))]),
      ),
      cssVariables: { light, dark },
      typography: resolved.typography,
    },
    null,
    2,
  ) + '\n',
);
console.log(`theme css written: ${Object.keys(light).length} light vars, ${Object.keys(dark).length} dark overrides`);
